using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class FinalCaveHillsideViews{
 public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/LakeWoods.unity");Physics.SyncTransforms();var b=Object.FindObjectsByType<WoodlandRoute>().Single(x=>x.title=="Echo Cave");var race=Object.FindAnyObjectByType<RaceDirector>();var car=race.vehicle;typeof(ArcadeVehicle).GetMethod("Awake",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(car,null);var config=car.GetComponent<VehicleConfiguration>()??car.gameObject.AddComponent<VehicleConfiguration>();var chase=Object.FindAnyObjectByType<ChaseCamera>();var cam=chase.GetComponent<Camera>();var rows=new List<string>();
 foreach(var profile in new[]{"moto","atv"}){config.Apply(profile);foreach(float s in new[]{185f,197f}){var p=b.At(s,out var f);car.transform.SetPositionAndRotation(p+Vector3.up*.55f,Quaternion.LookRotation(Vector3.ProjectOnPlane(f,Vector3.up)));chase.target=car.transform;chase.Snap();Physics.SyncTransforms();typeof(ChaseCamera).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(chase,null);var rt=new RenderTexture(1200,750,24);var prior=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1200,750,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1200,750),0,0);tex.Apply();File.WriteAllBytes("Docs/CaveHillside/"+profile+"-chase-"+s+".png",tex.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=prior;rt.Release();Object.DestroyImmediate(tex);Object.DestroyImmediate(rt);rows.Add(profile+" station="+s+" camera="+cam.transform.position+" offset="+chase.offset);}}
 File.WriteAllLines("Docs/CaveHillside/driving-camera-positions.txt",rows);EditorSceneManager.OpenScene("Assets/Scenes/LakeWoods.unity");return "Production motorcycle and ATV chase cameras captured; temporary vehicle changes discarded";}
}
